from pathlib import Path
import sys

p = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('psico-engine.js')
s = p.read_text(encoding='utf-8')

marker = "\n/* PLACURSO_PHASE2_PROGRESSION */\n"
if marker in s:
    raise SystemExit('Fase 2 já aplicada.')

script = r'''\n/* PLACURSO_PHASE2_PROGRESSION */\n(function(){\n  function boot(){\n    var hub=document.querySelector('.pch-games-hub');\n    if(!hub || hub.dataset.phase2==='1') return;\n    hub.dataset.phase2='1';\n    var KEY='placurso_phase2_progress_v1';\n    var state={level:1,xp:0,plays:0,correct:0,totalTime:0,areas:{mente:{plays:0,correct:0},foco:{plays:0,correct:0},estrategia:{plays:0,correct:0}}};\n    try{state=Object.assign(state,JSON.parse(localStorage.getItem(KEY)||'{}'));}catch(e){}\n    state.areas=Object.assign({mente:{plays:0,correct:0},foco:{plays:0,correct:0},estrategia:{plays:0,correct:0}},state.areas||{});\n    function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}\n    function areaName(){var a=state.areas, best='mente', bestScore=-1;Object.keys(a).forEach(function(k){var v=a[k],score=v.plays?v.correct/v.plays:0;if(v.plays>0&&score>bestScore){best=k;bestScore=score;}});return best;}\n    function weakArea(){var a=state.areas, worst=null,worstScore=2;Object.keys(a).forEach(function(k){var v=a[k],score=v.plays?v.correct/v.plays:0;if(v.plays>0&&score<worstScore){worst=k;worstScore=score;}});return worst||'mente';}\n    function render(){\n      var old=hub.querySelector('#annanPhase2Progress'); if(old) old.remove();\n      var card=document.createElement('section'); card.id='annanPhase2Progress'; card.className='pch-phase2-progress';\n      var pct=Math.min(100,Math.round((state.xp/300)*100));\n      var label=state.level===1?'Explorador':state.level===2?'Praticante':state.level===3?'Desafiador':'Mestre';\n      var weak=weakArea(), best=areaName();\n      card.innerHTML='<div class="pch-phase2-top"><div><span class="pch-games-eyebrow">ANNAN · PROGRESSÃO</span><h3>Seu progresso</h3><p>'+label+' · Nível '+state.level+' · '+state.xp+' XP</p></div><strong>'+pct+'%</strong></div><div class="pch-phase2-bar"><span style="width:'+pct+'%"></span></div><div class="pch-phase2-stats"><span>🎮 '+state.plays+' partidas</span><span>✓ '+state.correct+' acertos</span><span>⏱ '+Math.round(state.totalTime)+'s</span></div><p class="pch-phase2-note">ANNAN: melhor área <b>'+best+'</b>. Próximo foco: <b>'+weak+'</b>. Repetir com variação ajuda a transformar tentativa em experiência.</p>';\n      var first=hub.querySelector('.pch-games-nav'); if(first) first.after(card); else hub.prepend(card);\n    }\n    var css=document.createElement('style');css.textContent='.pch-phase2-progress{margin:12px 0;padding:14px;border:1px solid #D9C8A7;border-radius:17px;background:#fffdf8}.pch-phase2-top{display:flex;justify-content:space-between;gap:10px;align-items:start}.pch-phase2-top h3{margin:4px 0 2px;font-size:18px}.pch-phase2-top p{margin:0;color:#756D60;font-size:11px}.pch-phase2-top>strong{font-size:18px}.pch-phase2-bar{height:8px;margin:11px 0;border-radius:99px;background:#EEE6D6;overflow:hidden}.pch-phase2-bar span{display:block;height:100%;border-radius:99px;background:#A43D2F}.pch-phase2-stats{display:flex;gap:10px;flex-wrap:wrap;font-size:10px;font-weight:800;color:#574E42}.pch-phase2-note{margin:10px 0 0;font-size:11px;line-height:1.5;color:#756D60}@media(max-width:720px){.pch-phase2-stats{display:grid;grid-template-columns:1fr 1fr 1fr;gap:5px}}';document.head.appendChild(css);render();\n    var started=0,startedAt=0,activeKind='mente';\n    hub.addEventListener('click',function(ev){\n      var micro=ev.target.closest('[data-microgame]');\n      if(micro){activeKind=micro.dataset.microgame==='focus'?'foco':micro.dataset.microgame==='decision'?'estrategia':'mente';started=1;startedAt=Date.now();return;}\n      var answer=ev.target.closest('#annanMicroRunner [data-answer]');\n      if(answer && started){\n        state.plays++;state.areas[activeKind].plays++;var ok=answer.dataset.answer==='0';if(ok){state.correct++;state.areas[activeKind].correct++;state.xp+=state.level*10;}else{state.xp+=3;}state.totalTime+=Math.max(1,(Date.now()-startedAt)/1000);if(state.xp>=300)state.level=4;else if(state.xp>=180)state.level=3;else if(state.xp>=80)state.level=2;save();render();started=0;\n      }\n    });\n    var observer=new MutationObserver(function(){if(hub.querySelector('#annanMicroRunner .pch-runner-result'))render();});observer.observe(hub,{subtree:true,childList:true});\n  }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();\n})();\n'''
s += marker + script
p.write_text(s, encoding='utf-8')
print('OK: Fase 2 adicionada ao motor de progressão.')
